import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/widgets/zaylo_widgets.dart';import '../../models/zaylo_models.dart';import '../../repositories/providers.dart';
class CommunityScreen extends ConsumerWidget{const CommunityScreen({super.key});@override Widget build(BuildContext context,WidgetRef ref){final posts=ref.watch(mockRepositoryProvider).posts();return Scaffold(appBar:AppBar(title:const Text('Community')),floatingActionButton:FloatingActionButton.extended(onPressed:()=>showComingSoon(context,'Create post with category, comments and images'),label:const Text('Post'),icon:const Icon(Icons.add)),body:ListView(padding:const EdgeInsets.all(16),children:[const ZayloCard(child:Text('Community-submitted information may be reviewed by Zaylo AI and administrators. Please report incorrect or unsafe information.')),Wrap(spacing:8,children:['General','Jobs','Students','Farming','Prices','Rentals','Outages'].map((c)=>ActionChip(label:Text(c),onPressed:()=>showComingSoon(context,c))).toList()),for(final p in posts) ZayloCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Chip(label:Text(p.category)),const Spacer(),TrustBadge(p.status==VerificationStatus.verified)]),Text(p.body,style:Theme.of(context).textTheme.titleMedium),Text('${p.author} • ${p.createdAt.hour}:${p.createdAt.minute.toString().padLeft(2,'0')}'),ButtonBar(children:[TextButton.icon(onPressed:()=>showComingSoon(context,'Like'),icon:const Icon(Icons.thumb_up_outlined),label:Text('${p.likes}')),TextButton.icon(onPressed:()=>showComingSoon(context,'Comment'),icon:const Icon(Icons.comment_outlined),label:Text('${p.comments}')),IconButton(onPressed:()=>showComingSoon(context,'Save'),icon:const Icon(Icons.bookmark_border)),IconButton(onPressed:()=>showComingSoon(context,'Report'),icon:const Icon(Icons.flag_outlined))])]))]));}}
